r=[]
r.append(R(7247412,"फ्रेंच अनियन सूप","कैरेमलाइज़ किए हुए प्याज़ वाला यह आरामदायक सूप कोमल और मीठा दोनों है, और ऊपर से कुरकुरे क्रूटॉन इसे पूरा करते हैं।","4","590 ग्राम",
["3 छोटे चम्मच सूरजमुखी का तेल","1 किलो प्याज़, बारीक कटे हुए","400 ग्राम शकरकंद (12 फांकों में कटे हुए)","1 कम नमक वाला वेजिटेबल स्टॉक क्यूब, 800 मिलीलीटर उबलते पानी में घुला हुआ","साबुत गेहूँ की ब्रेड के 4 स्लाइस (प्रति स्लाइस 30 ग्राम)","20 ग्राम कम वसा वाला पुराना चेडर चीज़","20 ग्राम मोज़ेरेला","1 बड़ा चम्मच ताज़ा अजमोद (पार्सले), बारीक कटा हुआ, साथ में ऊपर से डालने के लिए थोड़ा और","एक अच्छी चुटकी काली मिर्च","1 छोटा चम्मच कम नमक वाला सोया सॉस"],
["ओवन को 190°C/गैस 5 पर पहले से गरम करें। एक सॉसपैन में 2 छोटे चम्मच तेल डालें, फिर प्याज़ डालें और बहुत धीमी आँच पर 30-40 मिनट तक पकाएँ, नियमित रूप से चलाते रहें ताकि प्याज़ कैरेमलाइज़ हो जाए।","जब प्याज़ कैरेमलाइज़ हो रहा हो, तब बचा हुआ तेल एक बेकिंग शीट पर डालें। शकरकंद डालें और इधर-उधर करके उन पर तेल लपेट दें, फिर ओवन में 30-40 मिनट तक बेक करें।","प्याज़ में स्टॉक डालें, उबाल लाएँ और 5 मिनट तक हल्की आँच पर पकाएँ।","इस बीच, चीज़ वाले क्रूटॉन बनाने के लिए: ब्रेड के हर स्लाइस को आधा काटें और ग्रिल करें, फिर पलटकर हर एक पर चेडर चीज़ और मोज़ेरेला रखें और चीज़ के पिघलने और भूरा होने तक फिर से ग्रिल करें। वैकल्पिक रूप से, आप चीज़ लगी ब्रेड को बेकिंग शीट पर रखकर ओवन में 5-10 मिनट तक पका सकते हैं।","अजमोद, काली मिर्च और सोया सॉस को सूप में मिलाएँ, फिर चार कटोरों में डालें। चीज़ वाले क्रूटॉन और ऊपर से ताज़े अजमोद के छिड़काव के साथ, और शकरकंद की फांकें किनारे पर रखकर परोसें।"],
[FV(4)]))
r.append(R(7249160,"प्लांटेन चिप्स","चिप्स के पैकेट की जगह इस ज़्यादा सेहतमंद और स्वादिष्ट नाश्ते को चुनें।","4","162 ग्राम",
["4 पके टमाटर, छिलका उतारे हुए और बीज निकाले हुए","1 छोटा लाल प्याज़, बारीक कटा हुआ","जूस में डिब्बाबंद अनानास के 2 छल्ले, बारीक कटे हुए","1 लाल मिर्च, बीज निकाली हुई और बारीक कटी हुई","2 बड़े चम्मच ताज़ा कटा धनिया","ताज़ा निचोड़ा हुआ नीबू का रस","½ छोटा चम्मच जर्क सीज़निंग","2 मध्यम हरे प्लांटेन (कच्चे केले)","2 छोटे चम्मच सूरजमुखी का तेल","½ छोटा चम्मच लहसुन नमक","½ छोटा चम्मच लहसुन के दाने (गार्लिक ग्रैन्यूल्स)","½ छोटा चम्मच काली मिर्च","चुटकी भर केयेन मिर्च (वैकल्पिक)"],
["ओवन को 190°C/फ़ैन ओवन 170°C/गैस 5 पर पहले से गरम करें। एक बड़ी बेकिंग ट्रे में नॉन-स्टिक बेकिंग पेपर बिछाएँ।","आधे टमाटरों को कांटे से मैश करके कटोरे में चम्मच से डालें। बचे हुए टमाटरों को मोटा काटें और उन्हें लाल प्याज़, अनानास, मिर्च, धनिया, स्वाद अनुसार नीबू का रस और जर्क सीज़निंग के साथ कटोरे में डालें। अच्छी तरह मिलने तक चलाएँ। स्वाद पकने के लिए 20 मिनट तक फ्रिज में रखें।","प्लांटेन को छीलें और 1/8 इंच मोटे स्लाइस में काटें। तेल, लहसुन के दानों और काली मिर्च में मिलाकर तैयार बेकिंग ट्रे पर एक परत में फैलाएँ।","15-18 मिनट तक बेक करें, जब तक कि पूरी तरह पक न जाए। ठंडा होने दें और अगर पसंद हो तो केयेन मिर्च छिड़कें।"],
[FV(1)]))
r.append(R(7250013,"बीफ़ स्ट्यू और डम्पलिंग","एक क्लासिक व्यंजन का ज़्यादा सेहतमंद रूप, जिसमें अतिरिक्त सब्ज़ियाँ और गाढ़ी ग्रेवी है।","6","379 ग्राम",
["1 छोटा चम्मच सूरजमुखी का तेल","500 ग्राम दुबला बीफ़, टुकड़ों में कटा हुआ","300 ग्राम प्याज़, कटे हुए","300 ग्राम गाजर, कटी हुई","1 डंठल सेलरी (60 ग्राम), कटी हुई","250 ग्राम मशरूम, कटे हुए","300 ग्राम आलू, छोटे टुकड़ों में कटे हुए","1 बड़ा चम्मच मैदा","1 कम नमक वाला स्टॉक क्यूब (बीफ़ या वेजिटेबल), 1.5 लीटर उबलते पानी में घुला हुआ",("डम्पलिंग के लिए","200 ग्राम साबुत गेहूँ का आटा"),("डम्पलिंग के लिए","1 छोटा चम्मच बेकिंग पाउडर"),("डम्पलिंग के लिए","एक अच्छी चुटकी सफ़ेद मिर्च"),("डम्पलिंग के लिए","1 छोटा चम्मच सूखा थाइम"),("डम्पलिंग के लिए","1 बड़ा चम्मच कटा हुआ ताज़ा अजमोद (पार्सले)"),("डम्पलिंग के लिए","100 मिलीलीटर सेमी-स्किम्ड दूध"),("डम्पलिंग के लिए","1 छोटा चम्मच जैतून का तेल")],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। एक बड़े पैन में तेल डालें, और 2-3 मिनट बाद बीफ़ डालें। 2 मिनट चलाएँ, फिर जब मांस सील हो जाए, तो प्याज़, गाजर, सेलरी और मशरूम डालें और 3-4 मिनट तक पकाएँ।","आलू डालें और मैदा छिड़कें, ताकि बीफ़ और सब्ज़ियों पर बराबर लिपट जाए।","लगातार चलाते हुए धीरे-धीरे स्टॉक डालें। 2-3 मिनट तक हल्की आँच पर पकाएँ जब तक यह गाढ़ा न हो जाए।","आँच से उतारकर ओवन-प्रूफ़ डिश में डालें, ढककर ओवन में 1¼ घंटे तक पकाएँ।","जब स्ट्यू को पकते हुए 1 घंटा हो जाए, तब डम्पलिंग बनाएँ: आटा, बेकिंग पाउडर, काली मिर्च, थाइम और अजमोद को एक कटोरे में डालें, फिर धीरे-धीरे दूध मिलाएँ और अच्छी तरह मिलाकर नरम आटा गूँध लें। आटा हाथों में न चिपके, इसके लिए जैतून के तेल से अपने हाथों को चिकना करें, फिर आटे की छह गोलियाँ बनाकर एक तरफ़ रख दें।","डम्पलिंग को स्ट्यू के ऊपर रखें और बिना ढके 15-20 मिनट तक पकाएँ, जब तक कि वे हल्की परत के साथ पक न जाएँ, लेकिन अंदर से नरम रहें।"],
["बीफ़ की जगह मांस का विकल्प इस्तेमाल करके, या बस और सब्ज़ियाँ डालकर इस क्लासिक व्यंजन को शाकाहारी बनाएँ।","इस व्यंजन में कार्बोहाइड्रेट की मात्रा कम करने के लिए छोटी डम्पलिंग बनाएँ या उन्हें पूरी तरह छोड़ दें।",FV(1)]))
r.append(R(7252558,"मिर्च, अदरक और लहसुन के साथ स्टर-फ्राइड केल","यह चटकीला हरा व्यंजन जल्दी पक जाता है और चाइनीज़ खाने के साथ या ग्रिल की हुई मछली, मांस या चिकन के साथ अच्छा लगता है।","4","83 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","3 सेमी ताज़ा अदरक, छीला और बारीक कटा हुआ","2-3 लहसुन की फांकें, कुचली हुई","चुटकी भर चिली फ्लेक्स","200 ग्राम घुंघराले केल, कटे हुए (मोटे डंठल निकाले हुए)","4 बड़े चम्मच पानी","आधे नीबू का रस"],
["पैन को धीमी-मध्यम आँच पर रखकर उसमें तेल डालें और अदरक तथा लहसुन डालकर 1-2 मिनट तक अच्छी तरह मिलाएँ।","अब चिली फ्लेक्स डालें और एक मिनट और चलाएँ।","केल डालें और 2-3 मिनट तक अच्छी तरह मिलाएँ।","आँच तेज़ करें, पानी डालें, मिलाएँ, पैन पर ढक्कन लगाएँ और बीच-बीच में चलाते हुए 5-6 मिनट और पकाएँ।","नीबू का रस छिड़कें और परोसें।"],
["केल के डंठल खाने योग्य होते हैं, लेकिन उन्हें पत्तों से पकने में ज़्यादा समय लगेगा – अगर आप उन्हें पहले निकालकर बारीक काट लें, तो उन्हें पत्तों के साथ पका सकते हैं।","200 ग्राम केल को एक कटे हुए लीक और एक कटे हुए, बिना छिले सेब के साथ बहुत थोड़े पानी में पकाकर देखें।",FV(0)]))
r.append(R(7253865,"मिक्स्ड फ़िश चाउडर","एक गरमाहट देने वाला भरपेट सूप जो समुद्री भोजन के शौकीनों को बेहद पसंद आएगा।","6","327 ग्राम",
["15 ग्राम वेजिटेबल ऑयल-बेस्ड स्प्रेड","1 बड़ा प्याज़, कटा हुआ","1 तेज पत्ता","2 डंठल सेलरी, बारीक कटी हुई","450 ग्राम आटेदार आलू, चौकोर टुकड़ों में कटे हुए","25 ग्राम सूखा नारियल (डेसिकेटेड कोकोनट)","600 मिलीलीटर स्किम्ड दूध","600 मिलीलीटर फ़िश स्टॉक","450 ग्राम मिली-जुली बिना हड्डी और बिना त्वचा की मछली के फ़िलेट, टुकड़ों में कटे हुए","100 ग्राम पके हुए छिले झींगे","125 ग्राम जमे हुए मटर","125 ग्राम जमे हुए स्वीटकॉर्न के दाने",("परोसने के लिए","3 बड़े चम्मच ताज़ा अजमोद (पार्सले), कटा हुआ")],
["एक बड़े पैन में मक्खन पिघलाएँ, प्याज़, तेज पत्ता, सेलरी और आलू डालें और 3-4 मिनट तक भूनें।","नारियल, दूध और फ़िश स्टॉक डालें, उबाल लाएँ, ढक दें और 20-25 मिनट तक हल्की आँच पर पकाएँ, जब तक कि आलू पक न जाएँ।","कांटे की मदद से ज़्यादातर आलू को मैश करें और अच्छी तरह मिलाएँ।","मछली, झींगे, मटर और स्वीटकॉर्न को पैन में डालें और 5 मिनट और पकाते रहें या जब तक मछली पक न जाए।","अच्छी तरह मसाला डालें और ऊपर से अजमोद डालकर परोसें।"],
["अतिरिक्त सब्ज़ियाँ डालने के लिए, बस कुछ मशरूम या कटी हुई तोरी और एक कटी हुई लाल शिमला मिर्च भूनें और परोसने से ठीक पहले मिला दें।","स्टॉक के साथ 1 बड़ा चम्मच हल्का करी पेस्ट डालकर इसे मसालेदार बनाएँ। ऊपर से बारीक कटा धनिया छिड़ककर परोसें।",FV(1)]))
r.append(R(7256542,"मसालेदार भुने हुए छोले","ये कुरकुरे छोले चिप्स या मूँगफली का बढ़िया विकल्प हैं और फ़ाइबर का अच्छा स्रोत हैं।","4","50 ग्राम",
["400 ग्राम का डिब्बा छोले","2 छोटे चम्मच रेपसीड तेल","आधा छोटा चम्मच पिसा जीरा","आधा छोटा चम्मच लाल मिर्च पाउडर"],
["छोलों का पानी निकालें और धोएँ, और किचन पेपर से थपथपाकर सुखा लें।","ओवन को 190°C/गैस 5 पर पहले से गरम करें। एक बड़ी बेकिंग ट्रे में 1 छोटा चम्मच रेपसीड तेल लगाएँ और ट्रे को 3 मिनट के लिए ओवन में रखें।","छोलों को गरम बेकिंग ट्रे पर फैलाएँ और 15 मिनट तक पकाएँ, बराबर पकने के लिए दो-तीन बार मिलाते रहें।","ओवन से निकालें, छोलों को एक कटोरे में डालें और बचा हुआ तेल छिड़कें। अच्छी तरह मिलाएँ। जीरा और लाल मिर्च पाउडर डालें। फिर से मिलाएँ और वापस बेकिंग ट्रे पर डाल दें।","10-15 मिनट और भूनें जब तक कि वे भूरे और कुरकुरे न हो जाएँ।","तुरंत परोसें या ठंडा करके खाएँ।"],
["इन्हें एक दिन पहले बनाकर एयरटाइट डिब्बे में रखा जा सकता है। अगर आप इन्हें गरम परोसना चाहते हैं तो बस गरम ओवन में दो मिनट के लिए दोबारा गरम करें।","यह नाश्ता फल और सब्ज़ी के आधे हिस्से के रूप में गिना जाता है।",FV(0)]))
r.append(R(7256644,"शतावरी, मटर और हरी प्याज़ का रिसोटो","एक ताज़ा हरा रिसोटो जो एक भरपेट, आरामदायक व्यंजन बनता है।","3","493 ग्राम",
["4 हरी प्याज़ (स्प्रिंग अनियन), कटी हुई","200 ग्राम शतावरी (एस्पैरेगस), 1.5 सेमी के टुकड़ों में कटी हुई","1 ग्लूटेन-मुक्त वेजिटेबल स्टॉक क्यूब, 900 मिलीलीटर पानी में घुला हुआ","1 लहसुन की फांक, कुचली हुई","चुटकी भर सफ़ेद मिर्च","150 ग्राम आर्बोरियो चावल","150 ग्राम जमे हुए मटर, पिघलाए हुए","2 छोटे चम्मच आधी वसा वाला क्रेम फ्रेश","10 ग्राम मक्खन","10 ग्राम शाकाहारी शैली का पार्मेसन चीज़, बारीक कद्दूकस किया हुआ"],
["सॉसपैन में तेल डालें, फिर हरी प्याज़ और शतावरी के डंठल डालें, लेकिन सिरे नहीं। मध्यम आँच पर 1 मिनट चलाएँ। एक अलग पैन में स्टॉक गरम करें और हल्की आँच पर उबलने दें।","शतावरी के डंठलों और हरी प्याज़ में लहसुन और सफ़ेद मिर्च डालें। 1 मिनट चलाएँ, फिर चावल डालें। 2 मिनट और चलाएँ, लगभग दो कलछी स्टॉक डालें, इतना कि चावल बस ढक जाए, फिर से चलाएँ।","चावल को नियमित रूप से चलाते हुए, गरम स्टॉक थोड़ा-थोड़ा करके डालें, ताकि चावल बस ढका रहे। रिसोटो में बहुत हल्के बुलबुले उठते रहने चाहिए।","20 मिनट बाद, बचा हुआ स्टॉक, मटर और शतावरी के सिरे डालें। 2-5 मिनट चलाएँ, चखकर देखें कि चावल अल डेंटे (थोड़ा सख़्त) पका है।","क्रेम फ्रेश, मक्खन और चीज़ को ज़ोर से मिलाएँ। ढक दें और 2 मिनट रखा रहने दें, फिर परोसें।"],
["रिसोटो बनाते समय भारी तले वाला सॉसपैन या कैसरोल डिश इस्तेमाल करें, क्योंकि आप नहीं चाहते कि वह पकाते समय जल जाए।","चावल को बराबर पकाने के लिए पकाते समय लगातार चलाते रहें।",FV(2)]))
r.append(R(7260729,"टर्की और छोले की करी","बची हुई टर्की में जान डालने का यह एक बेहतरीन तरीका है (आप इसकी जगह पका हुआ चिकन इस्तेमाल कर सकते हैं)।","2","495 ग्राम",
["1 छोटा चम्मच तेल","1 प्याज़, कटा हुआ","1 बड़ा चम्मच मध्यम तीखा करी पेस्ट","300 मिलीलीटर चिकन स्टॉक","200 ग्राम पकी हुई टर्की, कटी हुई","400 ग्राम का डिब्बा छोले, छाने और धोए हुए","2 टमाटर, कटे हुए","2 बड़े चम्मच ग्रीक दही","सजाने के लिए धनिया"],
["नॉन-स्टिक पैन में तेल गरम करें। प्याज़ डालें और 2-3 मिनट तक नरम होने तक भूनें।","करी पेस्ट डालें और 1 मिनट और पकाते रहें।","स्टॉक, टर्की, छोले और टमाटर डालें और बिना ढके 15 मिनट तक हल्की आँच पर पकाएँ।","दही मिलाएँ।","भाप में पके चावल के साथ परोसें और धनिये से सजाएँ।"],
["करी को सलाद के साथ चपाती या रोटी में लपेटकर आज़माएँ।","अतिरिक्त सब्ज़ियों के लिए, प्याज़ के साथ एक कटी हुई लाल शिमला मिर्च डालें।",FV(2)]))
r.append(R(7262970,"एंडियन शैली की क्विनोआ","दक्षिण अमेरिका के मुख्य खाद्य पदार्थ क्विनोआ से बना एक स्वादिष्ट व्यंजन।","2","467 ग्राम",
["125 ग्राम क्विनोआ","1 बड़ा चम्मच जैतून का तेल","1 प्याज़, कटा हुआ","1 डंठल सेलरी, कटी हुई","1 तोरी, कटी हुई","1 मध्यम आलू, कटा हुआ","1 लाल मिर्च, बारीक कटी हुई","1 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच पिसा धनिया","400 ग्राम का डिब्बा कटे हुए टमाटर","1 छोटा चम्मच सूखा ऑरिगैनो","ताज़ी पिसी काली मिर्च","25 ग्राम अखरोट, कटे हुए"],
["क्विनोआ को 300 मिलीलीटर पानी के साथ पैन में रखें। उबाल लाएँ और 10-15 मिनट तक हल्की आँच पर पकाएँ जब तक कि सारा पानी सोख न लिया जाए। एक तरफ़ रख दें।","एक मध्यम सॉसपैन में तेल गरम करें और प्याज़ को 3-4 मिनट तक भूनें जब तक कि वह नरम होने न लगे।","सेलरी, तोरी और आलू डालें और 5-6 मिनट तक भूनते रहें।","फिर मिर्च, जीरा और धनिया डालें और एक मिनट और भूनें।","टमाटर और ऑरिगैनो डालें, काली मिर्च से अच्छी तरह मसाला डालें और 10-15 मिनट तक हल्की आँच पर पकाएँ, जब तक कि सब्ज़ियाँ नरम न हो जाएँ।","क्विनोआ और अखरोट मिलाएँ।"],
["क्विनोआ (उच्चारण: कीन-वा) पोषण की दृष्टि से एक साबुत अनाज है, लेकिन असल में यह एक बीज है। यह स्वाभाविक रूप से ग्लूटेन-मुक्त और प्रोटीन से भरपूर है। पुलाव और सलाद बनाने के लिए इसे चावल या कूसकूस की जगह इस्तेमाल करें।","आप शिमला मिर्च, मशरूम, मटर या स्वीटकॉर्न जैसी हर तरह की सब्ज़ियाँ डाल सकते हैं।",FV(4)]))
r.append(R(7263439,"श्पेट्सले","कम वसा वाला और सॉस के साथ, या स्ट्यू या कैसरोल के साथ छोटी प्लेट के रूप में परोसने पर स्वादिष्ट।","4","86 ग्राम",
["250 ग्राम मैदा","1 बड़ा अंडा, फेंटा हुआ","चुटकी भर जायफल","2 छोटे चम्मच जैतून का तेल","1 बड़ा चम्मच ताज़ा अजमोद (पार्सले), कटा हुआ"],
["एक बड़े सॉसपैन में पानी उबालें।","एक बड़े कटोरे में मैदा, अंडा और जायफल मिलाएँ। धीरे-धीरे लगभग 100 मिलीलीटर ठंडा पानी मिलाकर चिकना आटा बनाएँ जो चम्मच से न चिपके।","कटिंग बोर्ड पर आटा छिड़कें, उस पर आटे को रखें और पतला बेलें। आटे को लगभग 5 सेमी लंबे छोटे नूडल्स में काटें। नूडल्स को उबलते पानी में डालकर कुछ-कुछ करके पकाएँ। ये जल्दी पक जाते हैं और ऊपर तैरने लगें तो तैयार हैं। जैसे ही नूडल्स पक जाएँ, उन्हें छेदवाले चम्मच से निकाल लें।","नूडल्स को प्लेट में डालें और जैतून का तेल तथा थोड़ा अजमोद मिलाकर उछालें।"],
["ज़्यादा फ़ाइबर के लिए श्पेट्सले को आधे साबुत गेहूँ के आटे से बनाकर देखें।","2 लोगों के लिए एक आसान सॉस के लिए, एक बड़े कटे हुए लीक को 150 ग्राम मशरूम के साथ भूनें। 2 बड़े चम्मच कम वसा वाला लहसुन और जड़ी-बूटी वाला क्रीम चीज़ मिलाएँ।",FV(0)]))
r.append(R(7267024,"फुलौरी (तीखी सॉस के साथ मटर दाल के पकौड़े)","ये स्वादिष्ट निवाले एपेटाइज़र या स्टार्टर के रूप में बढ़िया हैं। इन्हें आमतौर पर डीप फ्राई किया जाता है, लेकिन ग्रिल करने से वसा और कैलोरी कम हो जाती है।","4","349 ग्राम",
["225 ग्राम स्प्लिट पीस (सूखी मटर की दाल)","1 मध्यम प्याज़, मोटा कटा हुआ","1 लहसुन की फांक","2 बड़े चम्मच मैदा","ताज़ी पिसी काली मिर्च","ब्रश से लगाने के लिए थोड़ा तेल",("तीखी मिर्च वाली सॉस के लिए","1 छोटा पपीता, छीला, बीज निकाला हुआ और कटा हुआ"),("तीखी मिर्च वाली सॉस के लिए","1-2 बड़ी लाल मिर्च, बारीक कटी हुई"),("तीखी मिर्च वाली सॉस के लिए","1 छोटा प्याज़, बारीक कटा हुआ"),("तीखी मिर्च वाली सॉस के लिए","1 लहसुन की फांक, कुचली हुई"),("तीखी मिर्च वाली सॉस के लिए","1 बड़ा चम्मच सूखा सरसों पाउडर"),("तीखी मिर्च वाली सॉस के लिए","150 मिलीलीटर माल्ट सिरका")],
["स्प्लिट पीस को पैन में डालें, पानी से ढक दें और तेज़ उबाल पर 10 मिनट तक उबालें, फिर 25-30 मिनट तक नरम होने तक हल्की आँच पर पकाएँ। पानी निकाल दें।","फ़ूड प्रोसेसर या ब्लेंडर में डालें, प्याज़, लहसुन और मैदा डालें और चिकना होने तक ब्लेंड करें।","अच्छी तरह मसाला डालें। 16 टिक्कियाँ बनाएँ।","इस बीच, ग्रिल को तेज़ पर पहले से गरम करें।","टिक्कियों पर थोड़ा तेल लगाएँ और 4-5 मिनट तक सुनहरा होने तक ग्रिल करें, पकाने के आधे समय में पलट दें।","तीखी मिर्च वाली सॉस बनाने के लिए, सारी सामग्री को पैन में डालें, उबाल लाएँ और 20 मिनट तक हल्की आँच पर पकाएँ।","ब्लेंडर में डालें और लगभग चिकना होने तक ब्लेंड करें। पकौड़ों के साथ परोसें।"],
["तीखी मिर्च वाली सॉस के विकल्प के रूप में, 2-2 बड़े चम्मच कटा ताज़ा धनिया, पुदीना और अजमोद एक कुचली हुई लहसुन की फांक और 4-5 बड़े चम्मच कम वसा वाले दही के साथ ब्लेंड करके जड़ी-बूटी वाला डिप बनाएँ।","फ्रीज़ करने के निर्देश: पकौड़ों और सॉस को अलग-अलग फ्रीज़ करें। माइक्रोवेव में पिघलाएँ। पकौड़ों को दोबारा गरम करते समय सावधानी रखें क्योंकि वे बिखर सकते हैं।",FV(2)]))
r.append(R(7267124,"वेजी राइस के साथ खट्टे-मीठे मीटबॉल","मीटबॉल परिवार के रात के खाने के लिए आदर्श हैं – बच्चों को भी इन्हें बनाने में मदद करना पसंद आएगा।","2","395 ग्राम",
["75 ग्राम टर्की ब्रेस्ट का कीमा","आधा छोटा प्याज़, बारीक कटा हुआ","4 खाने के लिए तैयार सूखे खुबानी, बारीक कटे हुए","आधा बड़ा चम्मच ताज़ा अजमोद (पार्सले), कटा हुआ","1 बड़ा चम्मच ताज़ा ब्रेडक्रम्ब्स","थोड़ा सा फेंटा हुआ अंडा",("चावल के लिए","100 ग्राम बासमती चावल"),("चावल के लिए","1 बड़ा चम्मच जमे हुए स्वीटकॉर्न"),("चावल के लिए","1 बड़ा चम्मच जमे हुए मटर"),("चावल के लिए","आधी छोटी लाल या नारंगी शिमला मिर्च, कटी हुई"),("सॉस के लिए","1 छोटा चम्मच रेपसीड तेल"),("सॉस के लिए","आधा छोटा प्याज़, बारीक कटा हुआ"),("सॉस के लिए","आधी छोटी लाल या नारंगी शिमला मिर्च, कटी हुई"),("सॉस के लिए","200 ग्राम का डिब्बा कटे हुए टमाटर"),("सॉस के लिए","1 छोटा चम्मच रेड वाइन सिरका")],
["ओवन को 200ºC/गैस 6 पर पहले से गरम करें। एक कटोरे में कीमा, प्याज़, खुबानी, अजमोद और ब्रेडक्रम्ब्स मिलाएँ। बाँधने के लिए पर्याप्त अंडा डालें और मिश्रण की 6-8 गोलियाँ बनाएँ। (बच्चों को मीटबॉल बनाने में मदद करने दें।) बेकिंग शीट पर रखें और 10-12 मिनट तक पकाएँ।","इस बीच, बासमती चावल को उसके पैकेट के निर्देशों के अनुसार पकाएँ, पकाने के समय के खत्म होने से 5 मिनट पहले स्वीटकॉर्न, मटर और शिमला मिर्च डालें।","सॉस बनाने के लिए, एक छोटे पैन में तेल गरम करें और प्याज़ तथा शिमला मिर्च डालें। 3 मिनट तक भूनें।","टमाटर और वाइन सिरका डालें। 1 मिनट तक हल्की आँच पर पकाएँ।","मिश्रण को पैन से निकालकर ब्लेंडर में डालें और चिकना होने तक ब्लेंड करें।","मिश्रण को वापस पैन में डालें और पके हुए मीटबॉल डालें।","1 मिनट तक गरम करें। मीटबॉल और सॉस को चावल पर परोसें।"],
["मीटबॉल अच्छी तरह फ्रीज़ हो जाते हैं, इसलिए एक बैच बनाकर फ्रीज़ करना अच्छा विचार है। आप अतिरिक्त सॉस भी बना सकते हैं और मीटबॉल और सॉस के अलग-अलग हिस्सों को प्लास्टिक के कपों में फ्रीज़ कर सकते हैं।","फ्रीज़ करने के निर्देश: सॉस और मीटबॉल को अलग-अलग फ्रीज़ करें। फ्रिज में या माइक्रोवेव में पिघलाएँ और पूरी तरह भाप निकलने तक अच्छी तरह दोबारा गरम करें।",FV(2)]))
r.append(R(7268954,"लैम्ब और शकरकंद हॉटपॉट","कुरकुरी, रंग-बिरंगी शकरकंद की परत इस पारंपरिक व्यंजन को एक सेहतमंद रूप देती है।","6","289 ग्राम",
["1 छोटा चम्मच रेपसीड तेल","500 ग्राम दुबले भेड़ की टाँग के स्टेक, टुकड़ों में कटे हुए","3 मध्यम प्याज़, कटे हुए","2 लीक, कटे हुए","3 मध्यम गाजर, कटी हुई","300 ग्राम शकरकंद, छीले और बड़े चौकोर टुकड़ों में कटे हुए, साथ में 150 ग्राम शकरकंद पतले स्लाइस में कटे हुए (कुल वज़न 400 ग्राम)","1 बड़ा चम्मच मैदा","1 कम नमक वाला भेड़ के मांस का स्टॉक क्यूब, 500 मिलीलीटर उबलते पानी में घुला हुआ","50 ग्राम स्प्लिट पीस (सूखी मटर की दाल)","तेज पत्ता","एक अच्छी चुटकी सफ़ेद मिर्च"],
["धीमी से मध्यम आँच पर सॉसपैन में तेल डालें, भेड़ का मांस डालें और 5 मिनट तक गरम करें।","प्याज़ डालें और नियमित रूप से चलाते हुए 5-7 मिनट तक हल्का भूरा करें।","लीक, गाजर और चौकोर कटी शकरकंद डालें, 2-3 मिनट चलाएँ।","सब्ज़ियों पर मैदा छिड़कें और अच्छी तरह मिलाएँ ताकि सारे टुकड़ों पर लिपट जाए।","स्टॉक मिलाएँ और स्प्लिट पीस, तेज पत्ता और सफ़ेद मिर्च डालें।","ढककर बीच-बीच में चलाते हुए 45 मिनट तक हल्की आँच पर पकाएँ, और अधिक तरल की ज़रूरत हो तो पानी डालें। लगभग 30 मिनट बाद अपना ओवन 180°C/गैस 4 पर पहले से गरम करें।","आँच से उतारें और ओवन-प्रूफ़ डिश में डालें। शकरकंद के स्लाइस ऊपर सजाएँ। 15-20 मिनट तक बेक करें, जब तक कि आलू सुनहरा भूरा न हो जाए और किनारों पर कुरकुरा न हो जाए।"],
["आप यह व्यंजन सूअर, बीफ़, चिकन के टुकड़ों, टर्की या दाल से भी बना सकते हैं।","कोई भी जड़ वाली सब्ज़ी अच्छी रहती है – गाजर, स्वीड और शलजम का मेल आज़माएँ।","फ्रीज़ करने के निर्देश: भागों में फ्रीज़ करें, फिर फ्रिज में पिघलाएँ, या माइक्रोवेव में पिघलाएँ, नियमित रूप से चलाने का ध्यान रखें।",FV(2)]))
r.append(R(7269383,"हॉर्सरैडिश के साथ मैकेरल, नए आलू और वॉटरक्रेस सलाद","यह रंग-बिरंगा सलाद स्वाद से भरपूर है और हॉर्सरैडिश से इसमें अतिरिक्त चटपटापन आता है! इस रेसिपी को Slimming World के साथ साझेदारी में चुना गया है।","4","480 ग्राम",
["600 ग्राम नए बेबी आलू","450 ग्राम (लगभग 6) ताज़ी मैकेरल मछली के फ़िलेट","2 नीबू का रस","1/2 छोटा चम्मच सूखी लाल मिर्च के फ्लेक्स","200 ग्राम जमे हुए मटर","150 ग्राम लाल पत्तागोभी, पतली कटी हुई","175 ग्राम बेबी प्लम टमाटर, आधे कटे हुए","100 ग्राम वॉटरक्रेस",("ड्रेसिंग के लिए","½ लाल प्याज़, बारीक कटा हुआ"),("ड्रेसिंग के लिए","75 ग्राम फ़ैट-फ़्री सादा बिना चीनी वाला दही"),("ड्रेसिंग के लिए","1 समतल बड़ा चम्मच तीखी हॉर्सरैडिश सॉस")],
["अपने ओवन को 220°C/फ़ैन 200°C/गैस 7 पर पहले से गरम करें। बेकिंग ट्रे में बेकिंग पेपर बिछाएँ।","आलुओं को 20 मिनट तक या नरम होने तक उबालें। पानी निकालें और मोटे स्लाइस में काटें। वापस पैन में डालें और ढक दें।","इस बीच, मैकेरल को त्वचा की तरफ़ नीचे करके तैयार बेकिंग ट्रे पर रखें। आधा नीबू का रस छिड़कें, काली मिर्च डालें और चिली फ्लेक्स छिड़कें। 15 मिनट तक बेक करें, फिर ठंडा होने दें। त्वचा उतारें और मछली को रेशों में तोड़ लें।","ड्रेसिंग के लिए, प्याज़, दही और हॉर्सरैडिश को बचे हुए नीबू के रस के साथ एक छोटे कटोरे में डालें। हल्के से फेंटें, फिर स्वाद अनुसार काली मिर्च डालें।","मटर को 1-2 मिनट तक उबालें। पानी निकालकर पत्तागोभी और टमाटर के साथ एक बड़े कटोरे में डालें। उछालकर मिलाएँ और आलू तथा वॉटरक्रेस डालकर फिर से मिलाएँ। चम्मच से 4 प्लेटों में डालें और ऊपर मैकेरल रखें। ड्रेसिंग को किनारे पर परोसें, ऊपर से काली मिर्च छिड़कें।"],
[FV(2)]))
r.append(R(7271556,"ब्लैककरेंट और रास्पबेरी आइसक्रीम","रसीली ब्लैककरेंट, रास्पबेरी और सोया दूध मिलकर एक स्वादिष्ट कम वसा वाली आइसक्रीम बनाते हैं।","4","282 ग्राम",
["600 मिलीलीटर बिना चीनी वाला सोया दूध","कुछ बूँदें वनीला एक्सट्रैक्ट","1 बड़ा चम्मच कॉर्नफ़्लोर","4 अंडे की ज़र्दी","2 बड़े चम्मच आइसिंग शुगर","300 ग्राम का डिब्बा फलों के रस में ब्लैककरेंट, छना हुआ","200 ग्राम जमी हुई रास्पबेरी"],
["दूध और वनीला एक्सट्रैक्ट को मध्यम पैन में डालें और उबाल लाएँ।","एक कटोरे में कॉर्नफ़्लोर, अंडे की ज़र्दी और आइसिंग शुगर को फेंटें।","दूध को कॉर्नफ़्लोर के मिश्रण पर डालें और मिलाएँ, फिर वापस पैन में डालें, धीमी आँच पर रखें और मिश्रण के गाढ़ा होने तक पकाएँ। उबालें नहीं, वरना मिश्रण फट जाएगा।","मिश्रण को ठंडा करें, फिर ब्लैककरेंट और रास्पबेरी मिलाएँ।","फ़्रीज़र में रखने योग्य डिब्बे में डालें।","2 घंटे तक फ्रीज़ करें, फिर बर्फ़ के कण हटाने के लिए कांटे से फेंटें। वापस फ़्रीज़र में रखें और जमने तक फ्रीज़ करें। परोसने से 5-10 मिनट पहले फ़्रीज़र से निकालें।"],
["यह तरीका ज़्यादातर फलों के साथ काम करता है – आम, स्ट्रॉबेरी या डिब्बाबंद आड़ू आज़माएँ।","फ्रीज़ करने के निर्देश: परोसने से कुछ मिनट पहले फ़्रीज़र से निकालें।",FV(1)]))
